cat >> src/lib/pagination.ts <<'EOF'

/**
 * Visits every item behind a cursor-paged listing, one page at a time. For
 * server-side walks (jobs, cascades) that must see the whole collection, not
 * just its first page. Stops if a cursor fails to advance, so a cursor the
 * repository cannot decode never turns into an endless loop.
 */
export async function forEachInPages<T>(
  fetchPage: (cursor: string | null) => Promise<Page<T>>,
  visit: (item: T) => Promise<void>,
): Promise<void> {
  let cursor: string | null = null;
  do {
    const page = await fetchPage(cursor);
    for (const item of page.items) await visit(item);
    cursor = page.nextCursor === cursor ? null : page.nextCursor;
  } while (cursor !== null);
}
EOF

