/**
 * Deletes every document of `orgId` that `keep` rejects, and any extra copy of
 * a kept subject beyond its most recently indexed one. The rebuild's last pass:
 * whatever the walk did not just re-index has no business being in the index.
 * Other tenants' documents are never read or touched.
 */
export async function pruneSearchDocuments(
  orgId: OrgId,
  keep: (subjectKind: SearchSubjectKind, subjectId: string) => boolean,
): Promise<number> {
  const db = getDb();

  const rows = db
    .select({
      id: searchIndex.id,
      subjectKind: searchIndex.subjectKind,
      subjectId: searchIndex.subjectId,
    })
    .from(searchIndex)
    .where(orgPredicate(searchIndex.orgId, orgId))
    .orderBy(desc(searchIndex.indexedAt), desc(searchIndex.id))
    .all();

  const seen = new Set<string>();
  const stale: string[] = [];
  for (const row of rows) {
    const key = `${row.subjectKind}:${row.subjectId}`;
    if (seen.has(key) || !keep(row.subjectKind, row.subjectId)) {
      stale.push(row.id);
    }
    seen.add(key);
  }

  for (let at = 0; at < stale.length; at += PRUNE_BATCH) {
    db.delete(searchIndex)
      .where(
        and(
          orgPredicate(searchIndex.orgId, orgId),
          inArray(searchIndex.id, stale.slice(at, at + PRUNE_BATCH)),
        ),
      )
      .run();
  }

  return stale.length;
}

/** Ids per `DELETE` in `pruneSearchDocuments`, well under SQLite's bind limit. */
const PRUNE_BATCH = 500;

/** Drift alarm input: how many documents this org currently has indexed. */

