 * included: archiving an issue takes its whole thread out of search.
 */
async function reindexIssueThread(orgId: OrgId, issueId: IssueId): Promise<void> {
  await reindexSubject(orgId, "issue", issueId);
  await forEachInPages(
    (cursor) =>
      commentRepo.listComments({
        orgId,
        issueId,
        includeArchived: true,
        limit: CASCADE_PAGE_SIZE,
        cursor,
