  await forEachInPages(
    (cursor) =>
      issueRepo.listIssues({
        orgId,
        projectId,
        includeArchived: true,
        limit: CASCADE_PAGE_SIZE,
        cursor,
      }),
    async (issue) => {
      await reindexIssueThread(orgId, issue.id);
