 * Walks one tenant's projects, issues and comments — every page of them — and
 * re-applies the searchability rule to each, then prunes whatever else is left
 * in that tenant's index. Scoped to a single org on purpose: a full-fleet
 * reindex is a sequence of these, so one slow tenant cannot stall the rest,
 * and no other tenant's documents are touched.
 *
 * Archived rows are read too and handed to the index writers, which decide
 * "is this searchable?" and drop the ones that are not. Only subjects the
 * writers actually indexed survive the final prune, so stale documents —
 * archived or deleted content, rows that no longer exist — cannot outlive a
 * rebuild.
 */
export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
  return runJob("search-reindex", async (result) => {
    const indexed = new Set<string>();
    const keep = (kind: SearchSubjectKind, subjectId: string) => {
      indexed.add(`${kind}:${subjectId}`);
    };

    await forEachInPages(
      (cursor) =>
        projectRepo.listProjects({
          orgId,
          limit: PAGE_SIZE,
          cursor,
          includeArchived: true,
        }),
      async (project) => {
        try {
          if (await indexProject(orgId, project)) keep("project", project.id);
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index project", {
            projectId: project.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      },
    );

    await forEachInPages(
      (cursor) =>
        issueRepo.listIssues({
          orgId,
          limit: PAGE_SIZE,
          cursor,
          includeArchived: true,
        }),
      async (issue) => {
        try {
          if (await indexIssue(orgId, issue)) keep("issue", issue.id);
          result.processed += 1;

          await forEachInPages(
            (cursor) =>
              commentRepo.listComments({
                orgId,
                issueId: issue.id,
                includeArchived: true,
                limit: PAGE_SIZE,
                cursor,
              }),
            async (comment) => {
              if (await indexComment(orgId, comment)) {
                keep("comment", comment.id);
              }
              result.processed += 1;
            },
          );
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index issue", {
            issueId: issue.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      },
    );

    const pruned = await searchRepo.pruneSearchDocuments(
      orgId,
      (kind, subjectId) => indexed.has(`${kind}:${subjectId}`),
    );
    logger.info("search index rebuilt", {
      orgId,
      indexed: indexed.size,
      pruned,
    });
  });
}
