  return projectService.createProject(tenant.actors.owner, { orgId: tenant.org.id, name, slug: name.toLowerCase(), key: "", description: null, visibility: "org", leadId: null, color: "#6366f1", targetDate: null });
}
async function mkIssue(tenant: Tenant, projectId: any, title: string) {
  return issueService.createIssue(tenant.actors.owner, issueInput(tenant.org.id, projectId, { title }));
}
async function mkComment(tenant: Tenant, issueId: any, body: string) {
  return commentService.createComment(tenant.actors.owner, { orgId: tenant.org.id, issueId, body, parentId: null, mentionedUserIds: [] });
}

describe("rule", () => {
  it("archiving an issue hides its comments", async () => {
    const i = await mkIssue(t, t.project.id, "AlphaIssue");
    const c = await mkComment(t, i.id, "AlphaComment");
    expect(await q(t, "Alpha")).toEqual([\`comment:\${c.id}\`, \`issue:\${i.id}\`].sort());
    await issueService.archiveIssue(t.actors.owner, t.org.id, i.id);
    expect(await q(t, "Alpha")).toEqual([]);
  });

  for (const archiveIssues of [true, false]) {
    it(\`archive/restore project archiveIssues=\${archiveIssues}\`, async () => {
      const tag = archiveIssues ? "Bravo" : "Charlie";
      const p = await mkProject(t, tag + "Proj");
      const early = await mkIssue(t, p.id, tag + "EarlyArchived");
      const earlyC = await mkComment(t, early.id, tag + "EarlyComment");
      await issueService.archiveIssue(t.actors.owner, t.org.id, early.id);
      const i = await mkIssue(t, p.id, tag + "Issue");
      const c = await mkComment(t, i.id, tag + "Comment");
      const d = await mkComment(t, i.id, tag + "DeletedComment");
      await commentService.deleteComment(t.actors.owner, { orgId: t.org.id, commentId: d.id });
      expect(await q(t, tag)).toEqual([\`project:\${p.id}\`, \`issue:\${i.id}\`, \`comment:\${c.id}\`].sort());

      await projectService.archiveProject(t.actors.owner, { orgId: t.org.id, projectId: p.id, archiveIssues });
      expect(await q(t, tag)).toEqual([]);

      let later: any = null;
      if (!archiveIssues) {
        later = await mkComment(t, i.id, tag + "LaterComment");
        await issueService.updateIssue(t.actors.owner, { orgId: t.org.id, issueId: i.id, title: tag + "EditedIssue" });
        expect(await q(t, tag)).toEqual([]);
      }

      await projectService.restoreProject(t.actors.owner, t.org.id, p.id);
      const expected = archiveIssues
        ? [\`project:\${p.id}\`]
        : [\`project:\${p.id}\`, \`issue:\${i.id}\`, \`comment:\${c.id}\`, \`comment:\${later.id}\`];
      expect(await q(t, tag)).toEqual(expected.sort());
      if (!archiveIssues) expect(await q(t, tag + "EditedIssue")).toEqual([\`issue:\${i.id}\`]);
      void earlyC;
    });
  }

  it("rebuild", async () => {
    // corrupt the index: stale entries, fake subjects, missing entries
    const p = await mkProject(t, "DeltaProj");
    const archived = await mkIssue(t, p.id, "DeltaArchived");
    await mkComment(t, archived.id, "DeltaArchivedComment");
    await issueService.archiveIssue(t.actors.owner, t.org.id, archived.id);
    await searchService.indexIssue; // noop
    await searchRepo.upsertSearchDocument(t.org.id, "issue", archived.id, "DeltaArchived stale", p.id);
    await searchRepo.upsertSearchDocument(t.org.id, "comment", "fake-comment", "Delta fake", null);
    await searchRepo.upsertSearchDocument(other.org.id, "comment", "fake-other", "Delta other fake", null);
    const otherIssue = await mkIssue(other, other.project.id, "DeltaOther");

    detach();
    const big: string[] = [];
    for (let n = 0; n < 130; n++) {
      const i = await mkIssue(t, t.project.id, "EchoIssue " + n);
      big.push("issue:" + i.id);
      const c = await mkComment(t, i.id, "EchoComment " + n);
      big.push("comment:" + c.id);
    }
    const many = await mkIssue(t, t.project.id, "FoxIssue");
    const manyC: string[] = ["issue:" + many.id];
    for (let n = 0; n < 120; n++) manyC.push("comment:" + (await mkComment(t, many.id, "FoxComment " + n)).id);
    detach = searchService.registerSearchListeners();
    expect((await q(t, "Echo")).length).toBe(0);

    const otherBefore = await searchRepo.countIndexed(other.org.id);
    const result = await runSearchReindexJob(t.org.id);
    expect(result.failed).toBe(0);
    expect(await q(t, "Delta")).toEqual([\`project:\${p.id}\`]);
    expect(await q(t, "Echo")).toEqual(big.sort());
    expect(await q(t, "Fox")).toEqual(manyC.sort());
    expect(await q(t, "Alpha")).toEqual([]);
    expect(await q(other, "Delta")).toEqual([\`comment:fake-other\`, \`issue:\${otherIssue.id}\`].sort());
    expect(await searchRepo.countIndexed(other.org.id)).toBe(otherBefore);

    // index count equals the set the rule allows
    const all = await q(t, "");
    expect(await searchRepo.countIndexed(t.org.id)).toBe(all.length);
  });
});
